diff --git a/spec/scripts/spec-status.js b/spec/scripts/spec-status.js
index b8dc025..82fbace 100644
--- a/spec/scripts/spec-status.js
+++ b/spec/scripts/spec-status.js
@@ -861,7 +861,7 @@ const waitClause = n => `${n} more open`
     out.push(cmd(lanes[0]))
     // "Is this parallelable?" must never be answered by the ABSENCE of the ⚡ header —
     // when other open work exists, the solo pick states it out loud.
-    if (later.length || blocked.length) out.push('   └─ 🚦 solo')
+    if (!later.length && !blocked.length) out.push('   └─ 🚦 solo')
   }
   // D3: when branch (c) below fires, the top pick it prints is also the head of `blocked` —
   // remembered here so --all's ⛔ section can filter it back out instead of re-printing it.
diff --git a/tests/queue/queue-overlay.test.js b/tests/queue/queue-overlay.test.js
index e4697c4..2c5e1fe 100644
--- a/tests/queue/queue-overlay.test.js
+++ b/tests/queue/queue-overlay.test.js
@@ -222,7 +222,7 @@ test('AC-20260909-08-9: default render prints a top prompt as the id-led cmd() r
   const lines = r.stdout.split('\n')
   const idxNext = lines.findIndex(l => l.includes('🎯 Next'))
   const nextBlockLines = lines.slice(idxNext + 1, lines.indexOf('', idxNext + 1))
-  assert.deepStrictEqual(nextBlockLines, ['q7  Backfill the escape ledger'],
+  assert.deepStrictEqual(nextBlockLines, ['q7  Backfill the escape ledger', '   └─ 🚦 solo'],
     'D9: the id-led cmd() row, one line, is the whole Next block — never the raw payload alone: ' + JSON.stringify(nextBlockLines))
 })

